function trackedCompetition({
  id,
  name,
  fullName = name,
  org,
  rel = 'A',
  loc,
  date,
  deadlineISO,
  tier = 'A',
  cat = 'AI 软件',
  match = 7.5,
  suit = '高',
  desc,
  strategy,
  audience,
  rewards,
  pros,
  cons,
  winning,
  timeline,
  sources,
  url,
  deadlines,
  primaryDeadline,
  verification,
  recordType,
  seriesId,
  parentId,
}) {
  return {
    id,
    name,
    fullName,
    org,
    rel,
    loc,
    date,
    deadlineISO,
    tier,
    cat,
    match,
    suit,
    desc,
    strategy,
    audience,
    rewards,
    pros,
    cons,
    winning,
    timeline: timeline ?? [{ event: '提交截止', date: deadlineISO, critical: true }],
    sources: sources ?? [{ title: `赛事页面｜${name}`, date: RADAR_UPDATED_AT, url }],
    url,
    ...(deadlines ? { deadlines } : {}),
    ...(primaryDeadline ? { primaryDeadline } : {}),
    ...(verification ? { verification } : {}),
    ...(recordType ? { recordType } : {}),
    ...(seriesId ? { seriesId } : {}),
    ...(parentId ? { parentId } : {}),
  };
}

function xfyunSkillCompetition({ id, name, fullName = name, flag, desc, strategy, match = 8.2, tier = 'A' }) {
  const url = `https://challenge.xfyun.cn/topic/info?type=${flag}`;
  return trackedCompetition({
    id,
    name,
    fullName,
    org: '科大讯飞 AI 开发者大赛 · SkillHub',
    rel: 'A+',
    loc: '线上 · 面向开发者 · 不限制开发平台',
    date: '截止 2026-08-27 17:00',
    deadlineISO: '2026-08-27',
    tier,
    cat: 'AI 软件',
    match,
    suit: match >= 8.8 ? '很高' : '高',
    desc,
    strategy,
    audience: 'AI Skill、Agent 工作流与自动化工具开发者',
    rewards: ['专家榜 5000 / 3000 / 2000 元', '另设热度榜', '单赛题总奖池 1.23 万元', 'SkillHub 生态展示'],
    pros: ['官方赛题与截止日明确', '技术平台不受限', '可沉淀为复用 Skill', '提交物结构清楚'],
    cons: ['需提交含 SKILL.md 的 ZIP', '需要同步 SkillHub', '同系列赛题较多、评审口径接近'],
    winning: ['任务完成率', 'Skill 说明质量', '真实工作流', '可复用与可安装'],
    url,
  });
}

